<script>
  import deepEqual from 'deep-equal';
  import throttle from 'lodash.throttle';
  import { createEventDispatcher, onMount, onDestroy } from 'svelte';
  import { config as configStore } from '../stores';
  import { fetchUrl } from '../fetch-url';
  import { createBranchUrl } from '../branch-utils';
  import { MAPBOX_GL_MAX_PITCH } from '../constants';
  import { MapboxOverlay } from '@deck.gl/mapbox';
  import { Tile3DLayer, TerrainLayer } from '@deck.gl/geo-layers';
  import { Tiles3DLoader } from '@loaders.gl/3d-tiles';
  import Color from 'color';
  import {
    LightingEffect,
    AmbientLight,
    DirectionalLight,
    PointLight,
    _CameraLight as CameraLight,
  } from '@deck.gl/core';
  import { _TerrainExtension as TerrainExtension } from '@deck.gl/extensions';

  export let id;
  export let bearing;
  export let center;
  export let pitch;
  export let showCollisions;
  export let showBoundaries;
  export let zoom;
  export let mapStyle;
  export let numberOfMaps;
  export let onMapMount;

  export let mapRenderer;

  let renderer;

  // Mapbox and MapLibre share a Map component since they are so similar and utilize the same methods
  const importRenderer = async () => {
    if (mapRenderer === 'maplibre-gl') {
      await import('maplibre-gl/dist/maplibre-gl.css');
      renderer = await import('maplibre-gl');
    } else if (mapRenderer === 'maptiler-sdk') {
      await import('@maptiler/sdk/dist/maptiler-sdk.css');
      renderer = await import('@maptiler/sdk');
      renderer.config.apiKey = $configStore.maptilerApiKey;
    } else {
      await import('mapbox-gl/dist/mapbox-gl.css');
      renderer = await import('mapbox-gl');
      renderer.accessToken = $configStore.mapboxGlAccessToken;

      // Set if your Mapbox flavored style uses a different server than `api.mapbox.com`.
      if ($configStore.mapboxBaseApiUrl) {
        renderer.baseApiUrl = $configStore.mapboxBaseApiUrl;
      }
    }
  };

  const dispatch = createEventDispatcher();

  let style = {};
  let url;
  let popup = null;
  let isPopupOpen = false;

  let map;
  let mapViewProps = {};

  let deckOverlay;

  // We can set style (an object) here because mapStyle only changes when it needs to
  $: ({
    style,
    url,
    precompile,
    selectedPrecompileOption,
    projection,
    deckGlLayer,
    landmarks3D,
  } = mapStyle);

  // We group map-view props here as they are useful in a few contexts
  $: mapViewProps = { bearing, center, pitch, zoom };

  const getCurrentMapView = () => {
    return {
      bearing: map.getBearing(),
      center: map.getCenter(),
      pitch: map.getPitch(),
      zoom: map.getZoom(),
    };
  };

  const shouldUpdateMapView = () => {
    return !deepEqual(getCurrentMapView(), mapViewProps);
  };

  const updateMapStyle = async (
    map,
    url,
    style,
    activePrecompileOptions,
    projection,
    deckGlLayer,
    landmarks3D
  ) => {
    if (!map) return;

    map.off('style.load', setProjection);

    if (deckOverlay) {
      map.removeControl(deckOverlay);
      deckOverlay = null;
    }

    let urlStr = url;
    if (!urlStr && mapStyle?.pattern) {
      urlStr = createBranchUrl(
        mapStyle?.pattern,
        mapStyle?.branch,
        mapStyle?.branchStyle
      );
    }

    let isUrl = !style && typeof urlStr === 'string';
    let stylesheet = style;

    if (precompile) {
      // If we're precompiling and nothing is selected, wait for a default to come through
      if (!activePrecompileOptions) return;

      if (isUrl) {
        stylesheet = await fetchUrl(urlStr);
      }

      if (!stylesheet) return;

      stylesheet = await precompile.script(stylesheet, activePrecompileOptions);

      map.setStyle(stylesheet);
    } else {
      map.setStyle(urlStr || style);
    }

    if (deckGlLayer && !!landmarks3D) {
      setTimeout(set3dLayer, 150);
    }

    if (projection && mapRenderer === 'maplibre-gl') {
      setTimeout(setProjection, 150);
    }
  };

  const updateMapFromProps = (map, mapView) => {
    if (!map || !shouldUpdateMapView(mapView)) return;
    map.jumpTo(mapView);
  };

  // The Mapbox/Maplibre popup requires HTML as a string
  // This means class names for the popup need to live in global.css
  // because Svelte won't compile unused CSS classes that live in this component
  const getPopupHtmlString = features => {
    const dedupedFeatures = features.reduce((acc, feature) => {
      const { source, sourceLayer, properties } = feature;
      const isDuplicate = acc.some(f => {
        const isSameSource =
          f.source === source && f.sourceLayer === sourceLayer;
        const hasSameProperties = Object.keys(properties).every(
          p => properties[p] === f.properties[p]
        );
        return isSameSource && hasSameProperties;
      });

      if (!isDuplicate) {
        acc.push(feature);
      }
      return acc;
    }, []);

    let html = '<div class="popup">';
    for (const feature of dedupedFeatures) {
      html += `<div class="popup-feature">`;
      const { properties, layer } = feature;
      html += `<div class="popup-label-heading">layer id</div>`;
      html += `<div class="popup-layer-id">${layer.id}</div>`;
      html += `<div class="popup-label-heading">source: source-layer</div>`;
      html += `<div class="popup-source-layer"><span class="popup-source">${feature.source}:</span> ${feature.sourceLayer}</div>`;
      if (properties && Object.keys(properties).length) {
        html += `<div class="popup-label-heading">properties</div>`;
        Object.keys(properties)
          .sort()
          .forEach(key => {
            const propertyValue = properties[key];
            html += `<p class="popup-property"><span class="popup-property-id">${key}:</span> <span class="popup-property-value">${propertyValue}</span></p>`;
          });
      } else {
        html += `<p class="popup-no-properties">No properties</p>`;
      }
      html += `</div>`;
    }
    html += '</div>';
    return html;
  };

  const setProjection = () => {
    if (!projection) return;
    map.setProjection({
      type: projection,
    });
  };

  function translateMapboxToDeckGl(mapboxLightPosition) {
    const pos = [
      mapboxLightPosition[2],
      ((mapboxLightPosition[1] - 90) % 180) * -1,
      mapboxLightPosition[0],
    ];

    return pos;
  }

  const set3dLayer = () => {
    const stylesheet = map.getStyle();
    const light = stylesheet?.light;
    const terrain = stylesheet?.terrain;
    const {
      data: deckGlData,
      beforeId,
      light: deckGlLight,
      opacity: deckGlOpacity,
    } = deckGlLayer;

    let ambientLight;
    let directionalLight;
    let pointLight;
    let cameraLight;
    let lightingEffect;

    // Temp pass through, this is redundant
    if (deckGlLight) {
      const { ambient, directional, point, camera } = deckGlLight;

      if (ambient) {
        if (!ambient.color) {
          ambient.color = 'rgb(255, 255, 255)';
        }
        ambient.color = Color(ambient.color).rgb().array();
        ambientLight = new AmbientLight(ambient);
      }

      if (directional) {
        if (!directional.color) {
          directional.color = 'rgb(255, 255, 255)';
        }
        directional.color = Color(directional.color).rgb().array();
        directionalLight = new DirectionalLight(directional);
      }

      if (point) {
        if (!point.color) {
          point.color = 'rgb(255, 255, 255)';
        }
        point.color = Color(point.color).rgb().array();
        pointLight = new PointLight(point);
      }

      if (camera) {
        if (!camera.color) {
          camera.color = 'rgb(255, 255, 255)';
        }
        camera.color = Color(camera.color).rgb().array();
        cameraLight = new CameraLight(camera);
      }

      lightingEffect = new LightingEffect({
        ...(ambientLight && { ambientLight }),
        ...(directionalLight && { directionalLight }),
        ...(pointLight && { pointLight }),
        ...(cameraLight && { cameraLight }),
      });
    } else if (light) {
      let { anchor, color, intensity, position } = light;

      if (!color) {
        color = 'rgb(255, 255, 255)';
      }

      color = Color(color).rgb().array();

      ambientLight = new AmbientLight({
        color: color,
        intensity: intensity * 5,
      });

      if (position) {
        directionalLight = new DirectionalLight({
          color: color,
          intensity: intensity * 10,
          direction: translateMapboxToDeckGl(position),
        });

        lightingEffect = new LightingEffect({
          ambientLight,
          directionalLight,
        });
      } else {
        lightingEffect = new LightingEffect({ ambientLight });
      }
    }

    let terrainLayer;
    let terrainExtension;

    if (terrain) {
      const { source: terrainSource, exaggeration } = terrain;
      const terrainSourceObj = stylesheet?.sources?.[terrainSource];
      const elevationData =
        terrainSourceObj?.url ?? terrainSourceObj?.tiles?.[0];

      terrainLayer = new TerrainLayer({
        id: 'terrain',
        minZoom: 0,
        maxZoom: 23,
        strategy: 'no-overlap',
        // Mapbox settings, see https://deck.gl/docs/api-reference/geo-layers/terrain-layer
        elevationDecoder: {
          rScaler: 6553.6 * exaggeration,
          gScaler: 25.6 * exaggeration,
          bScaler: 0.1 * exaggeration,
          offset: -10000 * exaggeration,
        },
        elevationData,
        color: [255, 255, 255, 0],
        operation: 'terrain+draw',
      });

      terrainExtension = new TerrainExtension();
    }

    const threeDlayer = new Tile3DLayer({
      id: 'tile-3d-layer',
      data: deckGlData,
      loader: Tiles3DLoader,
      opacity: deckGlOpacity ?? 1,
      // onTilesetLoad: tileset => {
      //   console.log('3D Tileset loaded:', tileset);
      // },
      onTilesetError: e => console.log(e),
      ...(beforeId && { beforeId }),
      ...(terrainExtension && { extensions: [terrainExtension] }),
    });

    if (!deckOverlay) {
      deckOverlay = new MapboxOverlay({
        interleaved: true,
        // Boolen filter in case terrain isn't available
        layers: [terrainLayer, threeDlayer].filter(Boolean),
        ...(lightingEffect && {
          effects: [lightingEffect],
        }),
      });

      map.addControl(deckOverlay);
    }
  };

  onMount(async () => {
    await importRenderer();
    const glLibrary = renderer;

    let isUrl = typeof url === 'string';
    let stylesheet;

    // This should get reset because the selectedPrecompileOption
    // usually doesn't exist here yet. This prevents an invalid stylesheet getting through
    if (precompile) {
      const activePrecompileOptions =
        selectedPrecompileOption ?? precompile?.options?.default;

      if (!activePrecompileOptions) return;

      if (isUrl) {
        stylesheet = await fetchUrl(url);
      }

      if (!stylesheet) return;

      if (precompile && precompile?.script) {
        stylesheet = await precompile.script(
          stylesheet,
          activePrecompileOptions
        );
      }
    }

    map = new glLibrary.Map({
      container: id,
      style: stylesheet ?? url,
      canvasContextAttributes: { preserveDrawingBuffer: true },
      preserveDrawingBuffer: true,
      maxPitch: MAPBOX_GL_MAX_PITCH,
      ...mapViewProps,
    });

    if (deckGlLayer && landmarks3D) {
      map.once('load', set3dLayer);
    }

    if (projection && mapRenderer === 'maplibre-gl') {
      map.on('style.load', () => {
        // Hacky but style.load is not reliable
        setTimeout(setProjection, 150);
      });
    }

    onMapMount(map);

    // Also focus map on wheel (automatically focused on click)
    const throttledWheelHandler = throttle(() => {
      document.getElementById(id).querySelector('canvas[tabindex="0"]').focus();
    }, 250);
    document
      .getElementById(id)
      .addEventListener('wheel', throttledWheelHandler, { passive: true });

    const handleMove = ({ origin }) => {
      const isFocused =
        document.getElementById(id)?.contains(document.activeElement) ?? false;
      if (isFocused) {
        dispatch('mapMove', { options: getCurrentMapView() });
      }
    };

    map.on('move', e => {
      if (!e?.resize) {
        handleMove(e);
      }
    });

    map.on('click', e => {
      let renderedFeatures = map.queryRenderedFeatures(e.point);
      if (!renderedFeatures.length) return;
      if (!isPopupOpen) {
        popup = new glLibrary.Popup()
          .setLngLat(e.lngLat)
          .setHTML(getPopupHtmlString(renderedFeatures))
          .setMaxWidth(360)
          .addTo(map);

        isPopupOpen = true;

        popup.on('close', () => {
          isPopupOpen = false;
        });
      } else {
        popup.remove();
        popup = null;
      }
    });
  });

  onDestroy(() => {
    if (map) {
      map.remove();
    }
  });

  // We check map and mapViewProps here to ensure this reacts to changes to
  // either
  $: updateMapFromProps(map, mapViewProps);

  $: updateMapStyle(
    map,
    url,
    style,
    selectedPrecompileOption,
    projection,
    deckGlLayer,
    landmarks3D
  );

  // Show collisions on the map as desired
  $: map && (map.showCollisionBoxes = showCollisions);

  // Show tile boundaries on the map as desired
  $: map && (map.showTileBoundaries = showBoundaries);

  // Resize the map when adding more maps and changing container size
  $: if (map && numberOfMaps) {
    // As of `v3.0.0` maplibre no longer needs this resizing: https://github.com/maplibre/maplibre-gl-js/blob/main/CHANGELOG.md#potentially-breaking-changes
    if (mapRenderer !== 'maplibre-gl' && mapRenderer !== 'maptiler-sdk') {
      map.once('render', () => {
        const container = document.getElementById(id);
        if (container) {
          const resizeObserver = new ResizeObserver(() => {
            map.resize({ resize: true });
          });
          resizeObserver.observe(container);
        }
      });
    }
  }
</script>

<div {id} class="map" />

<style>
  .map {
    height: 100%;
  }

  :global(.popup-label-heading) {
    font-size: 14px;
    color: #666;
    font-weight: 200;
    font-style: italic;
  }

  :global(.popup) {
    min-width: 180px;
    padding-right: 12px;
    max-height: 240px;
    overflow: auto;
  }

  :global(.popup-feature) {
    margin-top: 18px;
    margin-left: 3px;
  }

  :global(.popup-feature):first-child {
    margin-top: 0;
  }

  :global(.popup-layer-id) {
    font-weight: 600;
    font-size: 16px;
    line-height: 16px;
    margin-bottom: 6px;
  }

  :global(.popup-source) {
    font-weight: 600;
  }

  :global(.popup-source-layer) {
    font-size: 14px;
    line-height: 14px;
    margin-bottom: 6px;
    color: #666;
  }

  :global(.popup-property) {
    line-height: 6px;
    margin-top: 6px;
    margin-bottom: 3px;
    width: 100%;
    padding-bottom: 6px;
    border-bottom: 1px solid lightgray;
  }

  :global(.popup-no-properties) {
    border-bottom: 0px !important;
    color: lightgray;
  }

  :global(.popup-property-id) {
    font-weight: bold;
  }

  :global(.popup-property-value) {
    float: right;
  }

  :global(.mapboxgl-control-container .mapboxgl-ctrl-logo) {
    display: none;
  }
</style>
